1 Coríntios 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Paulo decidiu não saber de nada entre os coríntios senão de quê?","o":["Jesus Cristo, e este crucificado","A Lei de Moisés","A sabedoria dos gregos","Os milagres dos apóstolos"],"c":0,"v":2,"e":"No versículo 2, Paulo diz que decidiu não saber de nada senão de Jesus Cristo, e este crucificado."},
 {"t":"multipla","p":"Como Paulo diz que esteve entre os coríntios?","o":["Com grande ostentação de linguagem","Em fraqueza, temor e grande tremor","Com alegria e muita confiança","Em silêncio e oração"],"c":1,"v":3,"e":"No versículo 3, Paulo afirma que esteve entre eles em fraqueza, temor e grande tremor."},
 {"t":"multipla","p":"Em que Paulo queria que a fé dos coríntios se sustentasse?","o":["Na sabedoria humana","Na tradição dos antepassados","No poder de Deus","Na autoridade dos líderes"],"c":2,"v":5,"e":"No versículo 5, Paulo diz que a fé deles não deveria se sustentar na sabedoria humana, mas no poder de Deus."},
 {"t":"multipla","p":"Desde quando Deus preordenou a sabedoria que Paulo anuncia?","o":["Desde a eternidade","Desde o tempo de Moisés","Desde a ressurreição de Cristo","Desde o dia de Pentecostes"],"c":0,"v":7,"e":"No versículo 7, Paulo diz que Deus preordenou essa sabedoria desde a eternidade para a nossa glória."},
 {"t":"multipla","p":"Se os poderosos deste século tivessem conhecido a sabedoria de Deus, o que não teriam feito?","o":["Perseguido os apóstolos","Expulsado Paulo da cidade","Destruído o templo","Crucificado o Senhor da glória"],"c":3,"v":8,"e":"No versículo 8, Paulo diz que, se a tivessem conhecido, jamais teriam crucificado o Senhor da glória."},
 {"t":"cv","p":"Paulo compara: assim como só o espírito do homem conhece as coisas do homem, só o Espírito de Deus conhece as coisas de Deus.","c":true,"v":11,"e":"No versículo 11, Paulo faz exatamente essa comparação entre o espírito do homem e o Espírito de Deus."},
 {"t":"cv","p":"O homem natural compreende as coisas do Espírito de Deus, porque lhe parecem sabedoria.","c":false,"v":14,"e":"No versículo 14, Paulo diz que o homem natural não compreende essas coisas, pois lhe parecem loucura."},
 {"t":"cv","p":"Paulo termina o capítulo dizendo: \"nós temos a mente de Cristo\".","c":true,"v":16,"e":"No versículo 16, último do capítulo, Paulo afirma: \"Contudo, nós temos a mente de Cristo\"."}
]}

1 Coríntios 9 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo Paulo, o que os coríntios são em relação ao apostolado dele?","o":["O selo do seu apostolado","A coroa do seu apostolado","O fundamento do seu apostolado","A recompensa do seu apostolado"],"c":0,"v":2,"e":"No versículo 2, Paulo diz que os coríntios são o selo do seu apostolado no Senhor."},
 {"t":"multipla","p":"Paulo pergunta se só ele e quem não teriam o direito de deixar de trabalhar?","o":["Cefas","Barnabé","Timóteo","Apolo"],"c":1,"v":6,"e":"No versículo 6, Paulo pergunta se ele e Barnabé seriam os únicos sem esse direito."},
 {"t":"multipla","p":"Que trecho da lei de Moisés Paulo cita?","o":["Não cobiçarás o boi do teu próximo","Darás descanso ao boi no sábado","Não atarás a boca do boi enquanto pisa o trigo","O boi que trabalha será do seu dono"],"c":2,"v":9,"e":"No versículo 9, Paulo cita: Não atarás a boca do boi enquanto pisa o trigo."},
 {"t":"multipla","p":"Por que Paulo e seus companheiros não exerceram o direito de receber sustento dos coríntios?","o":["Porque não precisavam de nada","Porque os coríntios eram pobres","Porque a lei os proibia","Para não criar obstáculo ao evangelho de Cristo"],"c":3,"v":12,"e":"No versículo 12, Paulo diz que suportavam tudo para não criar obstáculo ao evangelho de Cristo."},
 {"t":"multipla","p":"O que o Senhor ordenou aos que proclamam o evangelho?","o":["Que vivam do evangelho","Que trabalhem com as próprias mãos","Que não aceitem nada de ninguém","Que sirvam no templo"],"c":0,"v":14,"e":"No versículo 14, Paulo diz que o Senhor ordenou que os que proclamam o evangelho vivam do evangelho."},
 {"t":"cv","p":"Paulo diz que sua recompensa é pregar o evangelho de graça.","c":true,"v":18,"e":"No versículo 18, Paulo diz que sua recompensa é pregar o evangelho de graça, sem tirar proveito do seu direito."},
 {"t":"cv","p":"Paulo lembra que, no estádio, todos os que correm recebem o prêmio.","c":false,"v":24,"e":"No versículo 24, Paulo diz que todos correm, mas apenas um recebe o prêmio."},
 {"t":"cv","p":"Paulo disciplina o próprio corpo para não ser desqualificado depois de pregar aos outros.","c":true,"v":27,"e":"No versículo 27, Paulo diz que disciplina o corpo para não ser desqualificado depois de pregar aos outros."}
]}

1 Coríntios 4 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que se exige dos despenseiros?","o":["Que cada um seja encontrado fiel","Que cada um seja sábio","Que cada um fale bem","Que cada um seja respeitado"],"c":0,"v":2,"e":"No versículo 2, Paulo diz que dos despenseiros se exige que cada um seja encontrado fiel."},
 {"t":"multipla","p":"Segundo Paulo, quem é que o julga?","o":["A igreja de Corinto","Um tribunal humano","Ele mesmo","O Senhor"],"c":3,"v":4,"e":"No versículo 4, Paulo afirma: \"quem me julga é o Senhor\"."},
 {"t":"multipla","p":"Paulo aplicou estas coisas figuradamente a si mesmo e a quem?","o":["Pedro","Apolo","Timóteo","Barnabé"],"c":1,"v":6,"e":"No versículo 6, Paulo diz que aplicou estas coisas a si e a Apolo, por causa dos coríntios."},
 {"t":"multipla","p":"O que os apóstolos fazem quando são injuriados?","o":["Ficam em silêncio","Se defendem","Bendizem","Vão embora"],"c":2,"v":12,"e":"No versículo 12, Paulo diz: \"quando somos injuriados, bendizemos\"."},
 {"t":"multipla","p":"Para que Paulo mandou Timóteo aos coríntios?","o":["Para lembrá-los dos caminhos de Paulo em Cristo Jesus","Para recolher uma oferta","Para julgar os orgulhosos","Para substituir Apolo"],"c":0,"v":17,"e":"No versículo 17, Paulo diz que Timóteo lhes lembraria os seus caminhos em Cristo Jesus."},
 {"t":"cv","p":"Paulo diz que Deus designou os apóstolos em primeiro lugar.","c":false,"v":9,"e":"No versículo 9, Paulo diz que Deus designou os apóstolos em último lugar, como condenados à morte."},
 {"t":"cv","p":"Paulo diz que os coríntios poderiam ter milhares de preceptores em Cristo, mas não muitos pais.","c":true,"v":15,"e":"No versículo 15, Paulo diz isso e acrescenta que ele os gerou em Cristo Jesus pelo evangelho."},
 {"t":"cv","p":"Segundo Paulo, o reino de Deus consiste em palavras.","c":false,"v":20,"e":"No versículo 20, Paulo diz que o reino de Deus não consiste em palavras, mas em poder."}
]}

1 Coríntios 6 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"O capítulo critica quem leva uma queixa contra outro irmão a juízo diante de quem?","o":["Diante dos injustos","Diante dos anciãos","Diante dos apóstolos","Diante dos sacerdotes"],"c":0,"v":1,"e":"O versículo 1 critica quem leva a questão a juízo diante dos injustos, e não diante dos santos."},
{"t":"multipla","p":"Além do mundo, quem o capítulo diz que os santos irão julgar?","o":["Os profetas","Os anjos","Os reis da terra","Os fariseus"],"c":1,"v":3,"e":"O versículo 3 pergunta: \"Não sabeis que nós iremos julgar os próprios anjos?\""},
{"t":"multipla","p":"Que pergunta o capítulo faz a quem tem processos contra os irmãos?","o":["Por que não procuram um juiz melhor?","Por que não oferecem um sacrifício?","Por que não preferem sofrer a injustiça?","Por que não mudam de cidade?"],"c":2,"v":7,"e":"O versículo 7 pergunta: \"Por que não preferem sofrer a injustiça? Por que não aceitam ser lesados?\""},
{"t":"multipla","p":"Em nome de quem o capítulo diz que eles foram lavados, santificados e justificados?","o":["Do apóstolo Paulo","De Moisés","Da igreja de Corinto","Do Senhor Jesus Cristo"],"c":3,"v":11,"e":"O versículo 11 diz que foram lavados, santificados e justificados em nome do Senhor Jesus Cristo e pelo Espírito do nosso Deus."},
{"t":"multipla","p":"\"Todas as coisas me são lícitas, mas...\" Como o capítulo completa essa frase?","o":["nem todas são boas","nem todas me convêm","nem todas são de Deus","nem todas são permitidas"],"c":1,"v":12,"e":"O versículo 12 diz: \"Todas as coisas me são lícitas, mas nem todas me convêm\"."},
{"t":"cv","p":"O capítulo diz que o corpo é para o Senhor, e o Senhor é para o corpo.","c":true,"v":13,"e":"O versículo 13 diz que o corpo não é para a impureza, mas para o Senhor, e o Senhor é para o corpo."},
{"t":"cv","p":"O capítulo afirma que vocês pertencem a si mesmos.","c":false,"v":19,"e":"O versículo 19 diz o contrário: o corpo é templo do Espírito Santo, e vocês não são de si mesmos."},
{"t":"cv","p":"Por terem sido comprados por preço, o capítulo manda glorificar a Deus no corpo e no espírito.","c":true,"v":20,"e":"O versículo 20 diz: \"fostes comprados por preço; agora, portanto, glorificai a Deus no vosso corpo e no vosso espírito\"."}
]}

1 Coríntios 11 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Paulo pede que os coríntios sejam imitadores dele, assim como ele é imitador de quem?","o":["De Cristo","De Pedro","De Moisés","De Apolo"],"c":0,"v":1,"e":"No versículo 1, Paulo diz: \"Sejam meus imitadores, assim como eu também sou de Cristo\"."},
 {"t":"multipla","p":"Segundo o capítulo, quem é a cabeça de Cristo?","o":["O homem","Deus","A igreja","Os anjos"],"c":1,"v":3,"e":"O versículo 3 afirma que \"Deus é a cabeça de Cristo\"."},
 {"t":"multipla","p":"O que Paulo diz ter ouvido sobre as reuniões da igreja em Corinto?","o":["Que havia divisões entre eles","Que faltava pão para a ceia","Que tinham deixado de orar","Que não se reuniam mais"],"c":0,"v":18,"e":"No versículo 18, Paulo diz que ouviu que, ao se reunirem na igreja, havia divisões entre eles."},
 {"t":"multipla","p":"O que acontecia quando os coríntios se reuniam para comer?","o":["Todos esperavam uns pelos outros","Repartiam tudo com os pobres","Uns passavam fome enquanto outro se embriagava","Ninguém comia nada"],"c":2,"v":21,"e":"O versículo 21 diz que cada um tomava antes a própria refeição, e uns passavam fome enquanto outro se embriagava."},
 {"t":"multipla","p":"O que Jesus disse que o cálice é?","o":["O pão da vida","A lei de Moisés","A promessa feita a Abraão","A nova aliança no seu sangue"],"c":3,"v":25,"e":"No versículo 25, Jesus diz: \"Este cálice é a nova aliança no meu sangue\"."},
 {"t":"cv","p":"Paulo afirma que o Senhor Jesus tomou o pão na noite em que foi traído.","c":true,"v":23,"e":"O versículo 23 diz que o Senhor Jesus, na noite em que foi traído, tomou o pão."},
 {"t":"cv","p":"Paulo manda que cada um examine o seu irmão antes de comer do pão e beber do cálice.","c":false,"v":28,"e":"O versículo 28 diz que cada um deve examinar a si mesmo, e não ao irmão."},
 {"t":"cv","p":"Paulo orienta que quem tiver fome coma em casa.","c":true,"v":34,"e":"No versículo 34, Paulo diz: \"se alguém tiver fome, que coma em casa\"."}
]}

1 Coríntios 5 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Que caso de imoralidade Paulo diz que havia entre os coríntios?","o":["Alguém tinha a mulher do próprio irmão","Alguém tinha a mulher do próprio pai","Alguém tinha a esposa de um presbítero","Alguém tinha duas esposas"],"c":1,"v":1,"e":"No versículo 1, Paulo fala de quem se atreve a tomar a mulher de seu próprio pai."},
 {"t":"multipla","p":"Como a igreja estava reagindo diante desse caso?","o":["Estava de luto e arrependida","Estava com medo de Paulo","Estava cheia de orgulho","Já tinha expulsado o homem"],"c":2,"v":2,"e":"No versículo 2, Paulo diz que eles estavam cheios de orgulho e nem se lamentaram."},
 {"t":"multipla","p":"Com que finalidade o homem seria entregue a Satanás?","o":["Para que o espírito seja salvo no Dia do Senhor Jesus","Para que a igreja ficasse livre de dívidas","Para que ele nunca mais voltasse à cidade","Para que servisse de exemplo aos gentios"],"c":0,"v":5,"e":"No versículo 5, a entrega é para a destruição da carne, a fim de que o espírito seja salvo no Dia do Senhor Jesus."},
 {"t":"multipla","p":"Que imagem Paulo usa para mostrar que um pouco de mal afeta todos?","o":["Um pouco de sal tempera a comida","Uma pequena faísca incendeia a floresta","Um pouco de fermento leveda toda a massa","Uma semente pequena vira uma grande árvore"],"c":2,"v":6,"e":"No versículo 6, Paulo pergunta se eles não sabem que um pouco de fermento leveda toda a massa."},
 {"t":"multipla","p":"Quem Paulo chama de \"nosso Cordeiro pascal\"?","o":["Moisés","Cristo","O próprio Paulo","Abraão"],"c":1,"v":7,"e":"No versículo 7, Paulo diz que Cristo, nosso Cordeiro pascal, foi oferecido em sacrifício por nós."},
 {"t":"cv","p":"Paulo diz que os cristãos devem evitar todo contato com os imorais, avarentos e idólatras deste mundo.","c":false,"v":10,"e":"No versículo 10, Paulo diz que não se refere aos deste mundo, pois então seria necessário sair do mundo."},
 {"t":"cv","p":"Com alguém que se diz irmão e é avarento ou beberrão, Paulo manda que nem mesmo comam junto.","c":true,"v":11,"e":"No versículo 11, Paulo diz que, com quem se chama irmão e vive assim, nem mesmo comam."},
 {"t":"cv","p":"Paulo termina dizendo que Deus julgará os de fora e manda a igreja afastar o ímpio do meio dela.","c":true,"v":13,"e":"No versículo 13, Paulo afirma que Deus julgará os de fora e ordena que afastem o ímpio."}
]}

1 Coríntios 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Por que Paulo deu leite aos coríntios, e não alimento sólido?","o":["Porque já estavam maduros na fé","Porque o alimento sólido era só para os líderes","Porque Apolo já tinha dado alimento sólido","Porque ainda não podiam suportá-lo"],"c":3,"v":2,"e":"No versículo 2, Paulo diz que lhes deu leite porque ainda não podiam suportar alimento sólido, nem agora podem."},
 {"t":"multipla","p":"Que nomes os coríntios usavam para dizer de quem eram?","o":["Paulo e Apolo","Pedro e Tiago","Paulo e Barnabé","Apolo e Timóteo"],"c":0,"v":4,"e":"No versículo 4, alguns diziam \"Eu sou de Paulo\" e outros \"Eu sou de Apolo\"."},
 {"t":"multipla","p":"Na comparação com a lavoura, o que Apolo fez?","o":["Plantou","Regou","Deu o crescimento","Colheu"],"c":1,"v":6,"e":"No versículo 6, Paulo diz: \"Eu plantei, Apolo regou; mas foi Deus quem deu o crescimento\"."},
 {"t":"multipla","p":"Qual é o fundamento além do qual ninguém pode estabelecer outro?","o":["A Lei de Moisés","O apóstolo Pedro","Jesus Cristo","Os apóstolos"],"c":2,"v":11,"e":"No versículo 11, Paulo diz que o fundamento já estabelecido é Jesus Cristo."},
 {"t":"multipla","p":"Pelo que a obra de cada um será testada?","o":["Pelo fogo","Pela água","Pela Lei","Pelos anciãos"],"c":0,"v":13,"e":"No versículo 13, Paulo diz que a obra de cada um pelo fogo será testada."},
 {"t":"cv","p":"Quem tiver a sua obra queimada perde a salvação.","c":false,"v":15,"e":"No versículo 15, Paulo diz que essa pessoa sofrerá dano, mas será salva como que através do fogo."},
 {"t":"cv","p":"Paulo diz que os coríntios são santuário de Deus e que o Espírito de Deus habita neles.","c":true,"v":16,"e":"No versículo 16, Paulo pergunta: \"Não sabeis que sois santuário de Deus e que o Espírito de Deus habita em vós?\""},
 {"t":"cv","p":"Paulo recomenda que cada um se glorie no líder que escolheu seguir.","c":false,"v":21,"e":"No versículo 21, Paulo diz que ninguém se glorie nos homens, pois tudo é deles."}
]}

1 Coríntios 8 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o capítulo, o que o amor faz?","o":["Edifica","Incha","Julga","Separa"],"c":0,"v":1,"e":"No começo do capítulo, Paulo diz que o saber incha, mas o amor edifica."},
 {"t":"multipla","p":"O que acontece com quem ama a Deus?","o":["Torna-se sábio em tudo","É conhecido por Ele","Fica livre de todo pecado","Passa a ensinar os outros"],"c":1,"v":3,"e":"Logo depois de falar do saber, o texto diz que quem ama a Deus é conhecido por Ele."},
 {"t":"multipla","p":"O que o capítulo diz sobre o ídolo?","o":["Tem poder sobre quem come","É um deus menor","Por si mesmo, não é nada no mundo","Protege o templo onde está"],"c":2,"v":4,"e":"Ao tratar do consumo das coisas sacrificadas, Paulo afirma que o ídolo, por si mesmo, não é nada no mundo."},
 {"t":"multipla","p":"Por meio de quem existem todas as coisas, segundo o capítulo?","o":["Dos anjos","De Moisés","Dos profetas","De Jesus Cristo"],"c":3,"v":6,"e":"O texto diz que há um só Senhor, Jesus Cristo, por meio de quem existem todas as coisas."},
 {"t":"multipla","p":"Por que a consciência de alguns se contamina ao comer alimentos sacrificados a ídolos?","o":["Porque é fraca","Porque comeram demais","Porque não oraram antes","Porque comeram em público"],"c":0,"v":7,"e":"Paulo explica que a consciência deles se contamina por ser fraca."},
 {"t":"cv","p":"O capítulo diz que o alimento nos recomenda a Deus.","c":false,"v":8,"e":"O texto diz o contrário: o alimento não nos recomenda a Deus, pois comendo nada ganhamos e não comendo nada nos falta."},
 {"t":"cv","p":"Paulo pede cuidado para que a liberdade não se torne tropeço para os fracos.","c":true,"v":9,"e":"Depois de falar do alimento, Paulo adverte que a liberdade não deve se tornar tropeço para os fracos."},
 {"t":"cv","p":"Paulo diz que, se o alimento levar seu irmão a tropeçar, nunca mais comerá carne.","c":true,"v":13,"e":"No fim do capítulo, Paulo declara que nunca mais comerá carne para não escandalizar o irmão."}
]}

1 Coríntios 7 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Em que caso marido e mulher podem se privar um do outro?","o":["Quando um dos dois decidir sozinho","Por mútuo consentimento, por um tempo, para se dedicar à oração","Sempre que houver uma festa religiosa","Quando um deles estiver viajando"],"c":1,"v":5,"e":"No versículo 5, Paulo diz que só podem se privar por mútuo consentimento e por tempo determinado, para se dedicarem à oração."},
 {"t":"multipla","p":"O que Paulo diz aos solteiros e viúvas que não conseguem se dominar?","o":["Que jejuem mais","Que se afastem da cidade","Que se casem","Que procurem os apóstolos"],"c":2,"v":9,"e":"No versículo 9, Paulo diz que se casem, pois é melhor casar-se do que viver em chamas."},
 {"t":"multipla","p":"O que fazer se o cônjuge descrente quiser se afastar?","o":["Que se afaste, pois Deus nos chamou à paz","Que seja impedido a todo custo","Que seja levado diante da igreja","Que o crente vá junto com ele"],"c":0,"v":15,"e":"No versículo 15, Paulo diz que, se o descrente quiser se afastar, que se afaste, pois Deus nos chamou à paz."},
 {"t":"multipla","p":"Segundo Paulo, o que realmente importa, mais do que circuncisão ou incircuncisão?","o":["Ter nascido judeu","Fazer muitas ofertas","Ser casado","Observar as ordenanças de Deus"],"c":3,"v":19,"e":"No versículo 19, Paulo diz que circuncisão e incircuncisão não são nada, mas o que importa é observar as ordenanças de Deus."},
 {"t":"multipla","p":"Segundo Paulo, o homem casado se ocupa em como agradar a quem?","o":["Aos seus pais","À sua esposa","Aos líderes da igreja","Aos seus vizinhos"],"c":1,"v":33,"e":"No versículo 33, Paulo diz que o casado se ocupa das coisas deste mundo, em como agradar à sua esposa."},
 {"t":"cv","p":"Paulo diz que a ordem para a mulher não se separar do marido vem dele mesmo, e não do Senhor.","c":false,"v":10,"e":"No versículo 10, Paulo diz que quem ordena isso aos casados é o Senhor, e não ele."},
 {"t":"cv","p":"Paulo afirma que quem se casa não peca, e a virgem que se casa também não peca.","c":true,"v":28,"e":"No versículo 28, Paulo diz que nem o homem nem a virgem pecam ao se casar."},
 {"t":"cv","p":"Se o marido falecer, a mulher fica livre para se casar com quem desejar, desde que seja no Senhor.","c":true,"v":39,"e":"No versículo 39, Paulo diz que, morto o marido, ela está livre para se casar com quem quiser, desde que seja no Senhor."}
]}

1 Coríntios 10 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo o capítulo, quem era a pedra espiritual da qual o povo bebia no deserto?","o":["Cristo","Moisés","Arão","O próprio Deus Pai"],"c":0,"v":4,"e":"O versículo 4 diz que bebiam de uma pedra espiritual que os seguia, e essa pedra era Cristo."},
 {"t":"multipla","p":"O que aconteceu com os que puseram o Senhor à prova?","o":["Caíram mortos em um só dia","Pereceram pelas mordeduras das serpentes","Foram destruídos pelo exterminador","Ficaram sem água no deserto"],"c":1,"v":9,"e":"O versículo 9 diz que os que puseram o Senhor à prova pereceram pelas mordeduras das serpentes."},
 {"t":"multipla","p":"Segundo o capítulo, o que Deus fará junto com a tentação?","o":["Tirará a tentação de imediato","Mandará um anjo para lutar por eles","Proverá o livramento, para que a possam suportar","Castigará quem os tentou"],"c":2,"v":13,"e":"O versículo 13 diz que Deus é fiel e, juntamente com a tentação, proverá o livramento, para que a possam suportar."},
 {"t":"multipla","p":"Por que os crentes, embora sejam muitos, são um só corpo?","o":["Porque todos foram batizados no mar","Porque todos moram na mesma cidade","Porque todos têm a mesma consciência","Porque todos participam do único pão"],"c":3,"v":17,"e":"O versículo 17 diz que são um só pão e um só corpo porque todos participam do único pão."},
 {"t":"multipla","p":"Segundo o capítulo, a quem os gentios oferecem seus sacrifícios?","o":["A Deus","Aos demônios","Aos anjos","Aos seus antepassados"],"c":1,"v":20,"e":"O versículo 20 diz que o que os gentios sacrificam é sacrificado aos demônios, e não a Deus."},
 {"t":"cv","p":"O capítulo diz que todas as coisas são lícitas, mas nem todas convêm.","c":true,"v":23,"e":"O versículo 23 diz que todas as coisas são lícitas, mas nem todas convêm e nem todas edificam."},
 {"t":"cv","p":"O capítulo manda perguntar a origem de tudo o que se compra no mercado antes de comer.","c":false,"v":25,"e":"O versículo 25 manda comer de tudo o que se vende no mercado sem nada perguntar por motivo de consciência."},
 {"t":"cv","p":"O capítulo ensina que, quer comam, quer bebam ou façam qualquer outra coisa, devem fazer tudo para a glória de Deus.","c":true,"v":31,"e":"O versículo 31 diz que, quer comam, quer bebam ou façam qualquer outra coisa, devem fazer tudo para a glória de Deus."}
]}
